import React, { useMemo } from 'react';
import { motion } from 'framer-motion';

interface AnimatedTextProps {
  text: string;
  className?: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div';
  preserveWhitespace?: boolean;
  onAnimationComplete?: () => void;
}

/**
 * AnimatedText - A component that renders text with a character-by-character animation
 * similar to Claude's interface but with more organic randomness.
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  className = '',
  element = 'p',
  preserveWhitespace = false,
  onAnimationComplete
}) => {
  // Split text into individual characters
  const characters = Array.from(text);

  // Generate organic delays with more variability
  const characterDelays = useMemo(() => {
    // Base timing parameters
    const baseDelay = 0.018;  // Base delay between characters
    const variationFactor = 0.6; // Amount of random variation (higher = more organic)
    const thinkingPauseProbability = 0.12; // Probability of a longer "thinking" pause

    // Characters that might cause longer pauses
    const punctuation = ['.', ',', '!', '?', ':', ';'];

    // Generate a custom delay for each character
    let delays = [];
    let cumulativeDelay = 0;

    for (let i = 0; i < characters.length; i++) {
      const char = characters[i];

      // Add base delay
      cumulativeDelay += baseDelay;

      // Add random variation
      const randomVariation = (Math.random() * 2 - 1) * baseDelay * variationFactor;
      cumulativeDelay += randomVariation;

      // Add extra pause after punctuation (like a human would)
      if (punctuation.includes(char)) {
        const punctuationPause = baseDelay * (2 + Math.random() * 2); // 2-4x base delay
        cumulativeDelay += punctuationPause;
      }

      // Occasionally add a longer "thinking" pause
      if (Math.random() < thinkingPauseProbability) {
        const thinkingPause = baseDelay * (1 + Math.random() * 5); // 1-6x base delay
        cumulativeDelay += thinkingPause;
      }

      delays.push(cumulativeDelay);
    }

    return delays;
  }, [text]);

  // Animation container variant
  const container = {
    hidden: {},
    visible: {
      transition: {
        when: 'beforeChildren'
      }
    }
  };

  // Character animation variant
  const child = {
    hidden: { 
      opacity: 0,
      display: 'inline-block'
    },
    visible: {
      opacity: 1,
      display: 'inline-block',
      transition: { 
        duration: 0.01, // Very quick appearance like Claude
        ease: "linear"
      }
    }
  };

  // Create the characters as motion.span elements
  const animatedCharacters = characters.map((char, index) => (
    <motion.span
      key={`${index}-${char}`}
      variants={child}
      initial="hidden"
      animate="visible"
      transition={{
        delay: characterDelays[index] || index * 0.018, // Use our organic delay
      }}
    >
      {char === ' ' ? '\u00A0' : char}
    </motion.span>
  ));

  // Render the appropriate element with the animated characters
  const commonProps = {
    className: `animated-text ${className}`,
    style: { whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const },
    onAnimationComplete
  };

  switch (element) {
    case 'h1':
      return <motion.h1 {...commonProps}>{animatedCharacters}</motion.h1>;
    case 'h2':
      return <motion.h2 {...commonProps}>{animatedCharacters}</motion.h2>;
    case 'h3':
      return <motion.h3 {...commonProps}>{animatedCharacters}</motion.h3>;
    case 'h4':
      return <motion.h4 {...commonProps}>{animatedCharacters}</motion.h4>;
    case 'span':
      return <motion.span {...commonProps}>{animatedCharacters}</motion.span>;
    case 'div':
      return <motion.div {...commonProps}>{animatedCharacters}</motion.div>;
    case 'p':
    default:
      return <motion.p {...commonProps}>{animatedCharacters}</motion.p>;
  }
};

export default AnimatedText;
